#include <stdint.h>
#include <stdbool.h>

volatile uint32_t shared_counter = 0;

void EXTI0_IRQHandler(void) {
    shared_counter++;
}

void SysTick_Handler(void) {
    if (shared_counter > 1000) {
        shared_counter = 0;
    }
}

int main(void) {
    while (1) {
        if (shared_counter == 500) {
            // Do something
        }
    }
}
